import * as core from './instruction-core.mjs';
import {instructionCases,instructionPages,instructionHelpTopics,instructionHelp,instructionQuestions,instructionComparison,instructionExample} from './instruction-content.mjs';
import {instructionScene,instructionTicket,instructionToyExample} from './instruction-art.mjs';
import {puppetArt} from './loft-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,attrs='',primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${label}</button>`;
const pageNames={purpose:'The request',plan:'Picture plan',strip:'Ready-made strip',words:'Our own words',read:'Human reader',keep:'Keep a version'};
const helpNames={purpose:'Purpose and invitation',planning:'Plan and draft',sentence:'A complete instruction',order:'Order and reason',cause:'Two explanations',revision:'Revise or proofread',computer:'This computer',example:'A toy-box example'};
const productionNames={'not-stated':'Not stated',typed:'Typed my words',dictated:'Dictated to a person',copied:'Copied ready-made words',mixed:'Mixed or other'};
const readingNames={unknown:'Unknown',self:'Read myself',together:'Read together'};
const intros={
 purpose:['Who will use this note?','Look at the request and what this reader knows. What should the note help them do?'],
 plan:['Make a little picture plan','Choose the actions you intend. Move them earlier or later, or tell a plan to a person.'],
 strip:['Arrange the ready-made sentences','Choose complete ready-made sentences, then try this strip one action at a time.'],
 words:['Say it, then write it if you like','Say, sign, point, use AAC, draw off-screen or dictate. A written transcript is optional.'],
 read:['Read our words together','A person reads these words with you. Ask a question and change an unclear part together.'],
 keep:['Keep this version as it is','An unfinished note or an unexpected result can be kept. Every page stays open.']
};
const sentence=(source,item)=>source.actions.find(a=>a.id===item.actionId)?.variants[item.variant]||'';
const sentenceList=(source,strip)=>strip.length?`<ol class="instruction-exact-strip">${strip.map(item=>`<li>${esc(sentence(source,item))}</li>`).join('')}</ol>`:'<p>The ready-made strip is empty.</p>';
function header(desk){return `<header class="instruction-heading"><a class="back" href="#${desk}">Back to my ${desk==='loft'?'puppet show':'Post Office'}</a><h1>Instructions for a reader</h1><p class="instruction-shared">Your instruction notebook is shared between these two desks.</p><a href="#${desk==='post'?'loft':'post'}/instructions">Open this notebook at the ${desk==='post'?'Story Loft':'Post Office'}</a></header>`;}
export function instructionEntry(desk){return `<aside class="instruction-entry"><span class="instruction-entry-art">${instructionTicket('fold')}</span><div><strong>A little plan for a reader</strong><p>Arrange picture ideas, try ready-made instructions, or tell a puppet your own words.</p><a class="secondary" href="#${desk}/instructions">Open the instruction notebook</a></div></aside>`;}
function sourceBoard(v){const c=v.source,w=v.case,compact=c.id==='pocket-note'?['Dot knows which note and envelope.','Put the note inside and seal the envelope.','The open envelope is too small for the unfolded note. Folding once makes it fit.']:['Kitten knows the way. Rabbit is new and cannot see the table from the fork.','Put the arrow at the fork and the welcome card on the table before inviting Rabbit. Either preparation may come first.','The arrow and card are not placed. Rabbit has not been invited.'];return `<aside class="instruction-source" aria-label="Request, reader knowledge and starting scene"><div class="instruction-compact-source"><p><strong>Reader:</strong> ${compact[0]}</p><p><strong>Wanted:</strong> ${compact[1]}</p><p><strong>Start:</strong> ${compact[2]}</p></div><div class="instruction-full-summary"><div class="instruction-request"><strong>The request</strong><p>${esc(c.request)}</p></div><p><strong>What the reader knows:</strong> ${esc(c.readerKnowledge)}</p><p><strong>Starting scene:</strong> ${esc(c.startingDescription)}</p></div><p class="instruction-plan-reminder"><strong>Picture plan:</strong> ${w.plan.length?w.plan.map(id=>esc(c.actions.find(a=>a.id===id)?.label)).join(' → '):'Still open. Point, talk, draw or choose pictures.'}</p><details class="instruction-full-source"><summary>Read the full request and look at the scene</summary><div><p><strong>The request:</strong> ${esc(c.request)}</p><p><strong>What the reader knows:</strong> ${esc(c.readerKnowledge)}</p><p><strong>Starting scene:</strong> ${esc(c.startingDescription)}</p><div class="instruction-scene">${instructionScene(c.id,c.startingScene)}</div>${hearButton(`${c.request} ${c.readerKnowledge} ${c.startingDescription}`,'Hear the request and scene')}</div></details></aside>`;}
function purposePage(v){return `<section class="instruction-purpose"><div class="instruction-reader">${puppetArt(v.source.reader==='Dot'?'dot':'kitten')}<p><strong>A note for ${esc(v.source.reader)}</strong><br>What does this reader need to do?</p></div><p>This is a short practical note for a helper. You can plan pictures, choose ready-made sentences, or use your own words.</p><div class="instruction-actions">${button('Make a picture plan','data-instruction-page="plan"',true)}${button('Go to our own words','data-instruction-page="words"')}</div></section>`;}
function moves(group,id,index,length){return `<div class="instruction-moves" role="group" aria-label="Move or remove ${esc(id)}">${button('Earlier',`data-instruction-edit="${group}" data-op="earlier" data-id="${id}" aria-label="Move ${esc(id)} earlier" ${index===0?'disabled':''}`)}${button('Later',`data-instruction-edit="${group}" data-op="later" data-id="${id}" aria-label="Move ${esc(id)} later" ${index===length-1?'disabled':''}`)}${button('Remove',`data-instruction-edit="${group}" data-op="remove" data-id="${id}" aria-label="Remove ${esc(id)}"`)}</div>`;}
function planPage(v){const c=v.source,w=v.case;return `<section><div id="instruction-plan" class="instruction-ticket-strip" tabindex="-1" aria-label="Current picture plan">${w.plan.length?`<ol>${w.plan.map((id,i)=>`<li><span class="instruction-ticket-art">${instructionTicket(id)}</span><strong>${esc(c.actions.find(a=>a.id===id).label)}</strong>${moves('plan',id,i,w.plan.length)}</li>`).join('')}</ol>`:'<p>No picture tickets yet. Choose an action below, or make a plan off-screen.</p>'}</div><div class="instruction-picture-choices" role="group" aria-label="Add a picture to the plan">${c.actions.map(a=>button(`<span class="instruction-ticket-art">${instructionTicket(a.id)}</span><span>Add: ${esc(a.label)}</span>`,`data-instruction-edit="plan" data-op="add" data-id="${a.id}" ${w.plan.includes(a.id)?'disabled':''}`)).join('')}</div><p>Your picture plan and ready-made sentence strip are separate. Changing one keeps the other as you left it.</p><div class="instruction-actions">${button('Copy this plan to the ready-made strip','data-instruction-copy',true)}${button('Arrange ready-made sentences','data-instruction-page="strip"')}</div><p class="tiny">Copying chooses ready-made wording A in this order. The sentences are ready-made, not your own words.</p></section>`;}
function stripPage(v){const c=v.source,w=v.case;return `<section><div id="instruction-strip" class="instruction-ticket-strip instruction-sentence-tickets" tabindex="-1" aria-label="Current ready-made sentence strip">${w.strip.length?`<ol>${w.strip.map((item,i)=>{const a=c.actions.find(a=>a.id===item.actionId);return `<li id="instruction-sentence-${a.id}" tabindex="-1"><div class="instruction-ticket-line"><span class="instruction-ticket-art">${instructionTicket(a.id)}</span><p>${esc(sentence(c,item))}</p></div><details class="instruction-wording" data-instruction-wording="${a.id}"><summary>Choose another ready-made wording</summary><fieldset><legend>Ready-made wording for ${esc(a.label.toLowerCase())}</legend>${Object.entries(a.variants).map(([variant,text])=>button(esc(text),`data-instruction-edit="strip" data-op="variant" data-id="${a.id}" data-variant="${variant}" aria-pressed="${item.variant===variant}"`)).join('')}</fieldset></details>${moves('strip',a.id,i,w.strip.length)}</li>`;}).join('')}</ol>`:'<p>No ready-made sentences yet. Choose a sentence below. A short or empty strip can be kept.</p>'}</div><div class="instruction-add-sentences" role="group" aria-label="Add a ready-made sentence">${c.actions.filter(a=>!w.strip.some(item=>item.actionId===a.id)).map(a=>`<fieldset><legend>${esc(a.label)}</legend>${Object.entries(a.variants).map(([variant,text])=>button(`Add: ${esc(text)}`,`data-instruction-edit="strip" data-op="add" data-id="${a.id}" data-variant="${variant}"`)).join('')}</fieldset>`).join('')}</div><p>This device is one example of a computer. It follows the programmed rules for these actions. It does not infer what you meant or run your own words.</p><div class="instruction-actions">${button('Try this ready-made strip','data-instruction-try',true)}</div>${runPanel(v)}${pastRuns(v)}</section>`;}
function runPanel(v){if(!v.run)return '<p class="instruction-run-empty">No current run is showing. Trying a strip freezes a new starting scene and its consequences.</p>';const r=v.run,c=r.source,n=v.cursor,last=n>=r.transitions.length,past=JSON.stringify(r.strip)!==JSON.stringify(v.case.strip),transition=n?r.transitions[n-1]:null;return `<section class="instruction-run" id="instruction-run" tabindex="-1" aria-label="Frozen run"><h3>${past?'Earlier frozen run':'Frozen run'} ${r.id}</h3><p>These are the exact ready-made sentences in this run:</p>${sentenceList(c,r.strip)}<div class="instruction-scene instruction-run-scene">${instructionScene(c.id,v.scene)}</div><p id="instruction-run-description" role="status">${transition?esc(transition.description):esc(c.startingDescription)}</p><div class="instruction-actions">${button('Previous scene',`data-instruction-step="-1" ${n===0?'disabled':''}`)}${button('Next scene',`data-instruction-step="1" ${last?'disabled':''}`)}</div>${last?`<div class="instruction-result"><p><strong>Actual modeled result:</strong> ${esc(r.description)}</p><p><strong>The original request:</strong> ${esc(c.request)}</p><p>${r.requestFulfilled?'This run serves the stated request.':'This run does not yet serve the stated request. You can keep it or change the strip.'}</p></div>`:'<p>Reveal each consequence when you choose. A new run starts from the starting scene.</p>'}${past?'<p>This is past work. It is not feedback on the current strip.</p>':''}</section>`;}
function pastRuns(v){return v.case.runs.length?`<details class="instruction-history"><summary>Earlier frozen runs (${v.case.runs.length})</summary><p>These snapshots describe earlier work. They do not replace your current strip or give feedback on it.</p>${[...v.case.runs].reverse().map(r=>`<details data-instruction-history-result><summary>Earlier frozen run ${r.id}</summary>${sentenceList(r.source,r.strip)}<p><strong>Starting scene:</strong> ${esc(r.source.startingDescription)}</p><ol>${r.transitions.map(t=>`<li><strong>${esc(t.wording)}</strong> ${esc(t.description)}<p>${esc(core.describeInstructionScene(r.source.id,t.after))}</p></li>`).join('')}</ol><p><strong>Earlier modeled result:</strong> ${esc(r.description)}</p>${JSON.stringify(r.strip)===JSON.stringify(v.case.strip)?button('Replay this frozen strip',`data-instruction-run="${r.id}"`):''}</details>`).join('')}</details>`:'';}

function reports(w){return `<details class="instruction-reports"><summary>Optional reports about making and reading</summary><label for="instruction-production">How were these words made?</label><select id="instruction-production" data-instruction-report="production">${Object.entries(productionNames).map(([id,label])=>`<option value="${id}" ${w.productionReport===id?'selected':''}>${label}</option>`).join('')}</select><label for="instruction-reading">How are we reading?</label><select id="instruction-reading" data-instruction-report="reading">${Object.entries(readingNames).map(([id,label])=>`<option value="${id}" ${w.readingReport===id?'selected':''}>${label}</option>`).join('')}</select><p class="tiny">These are optional reports, not verified independence. Narration and displayed help are recorded separately. No recording or transcript is needed.</p></details>`;}
function wordsPage(v){const w=v.case;return `<section><label for="instruction-text">Our words for a person to read (optional)</label><textarea id="instruction-text" data-instruction-text maxlength="1200" rows="7" autocomplete="off" spellcheck="false" aria-describedby="instruction-text-note">${esc(w.text)}</textarea><p class="tiny" id="instruction-text-note">Your exact words stay as written. Up to 1,200 characters for storage; length says nothing about writing quality. Your words never become runnable actions.</p><p id="instruction-text-error" role="alert" tabindex="-1" hidden></p><p data-instruction-human-stale ${w.humanRead&&!v.humanReadCurrent?'':'hidden'}>The earlier reader snapshot and comment refer to earlier words.</p>${reports(w)}<div class="instruction-actions">${button('Read our words together','data-instruction-read',true)}</div></section>`;}
function humanPage(v,desk){const h=v.humanRead,w=v.case;return `<section><p>Listen, point, speak, sign or use AAC with a person. The app does not judge the reader’s response.</p><div class="instruction-puppet-reader">${desk==='loft'?puppetArt(v.source.reader==='Dot'?'dot':'kitten'):''}<div><h3>Our current words</h3><blockquote class="instruction-verbatim">${w.text?esc(w.text):'The written draft is blank. You can share words off-screen.'}</blockquote>${w.text?hearButton(w.text,'Hear our current words'):''}</div></div><fieldset class="instruction-questions"><legend>A reader may ask</legend>${instructionQuestions.map(q=>button(esc(q),`data-instruction-question="${esc(q)}"`)).join('')}</fieldset><div class="instruction-actions">${button('Read our words together','data-instruction-read',true)}${button('Revise our words','data-instruction-page="words"')}</div>${h?`<section id="instruction-human" class="instruction-human-snapshot" tabindex="-1"><h3>${v.humanReadCurrent?'Words read together':'Earlier words read together'}</h3><p>${esc(h.question)}</p><blockquote class="instruction-verbatim">${h.text?esc(h.text):'No written transcript was given.'}</blockquote>${!v.humanReadCurrent?'<p>This snapshot and its comment refer to earlier words. Read the current words together to make a new snapshot.</p>':''}<label for="instruction-comment">Reader’s comment (optional)</label><textarea id="instruction-comment" data-instruction-comment aria-describedby="instruction-comment-note" maxlength="400" rows="3" autocomplete="off" spellcheck="false">${esc(h.comment)}</textarea><p class="tiny" id="instruction-comment-note">Up to 400 characters for storage. A puppet’s response may be voiced off-screen; it is ungraded.</p><p id="instruction-comment-error" role="alert" tabindex="-1" hidden></p></section>`:'<p>Choose a question or read together to keep a snapshot of the actual draft being read. No transcript of the conversation is required.</p>'}${reports(w)}</section>`;}
function keptSnapshot(k){return `<article class="instruction-kept" id="instruction-kept-${k.id}" tabindex="-1"><h3>Kept version ${k.id}</h3><p><strong>Picture plan:</strong> ${k.plan.length?k.plan.map(id=>esc(k.source.actions.find(a=>a.id===id)?.label)).join(' → '):'No pictures selected.'}</p>${sentenceList(k.source,k.strip)}<h4>Own words</h4><blockquote class="instruction-verbatim">${k.text?esc(k.text):'No written transcript given.'}</blockquote>${k.run?`<details data-instruction-history-result><summary>Embedded frozen run ${k.run.id}</summary>${sentenceList(k.run.source,k.run.strip)}<p>${esc(k.run.description)}</p></details>`:''}${k.humanRead?`<details><summary>Embedded human reader snapshot</summary><blockquote class="instruction-verbatim">${esc(k.humanRead.text)}</blockquote><p>${esc(k.humanRead.question)}</p><blockquote class="instruction-verbatim">${esc(k.humanRead.comment)}</blockquote></details>`:''}<p class="tiny">Production report: ${esc(productionNames[k.productionReport])}. Reading report: ${esc(readingNames[k.readingReport])}. Displayed help stays with this version.</p>${button('Update this version with the current draft',`data-instruction-update="${k.id}"`)}</article>`;}
function keepPage(v){return `<section><div class="instruction-actions">${button('Keep a new version','data-instruction-keep',true)}</div><p id="instruction-kept-status" tabindex="-1" role="status">Your current draft stays separate from kept versions.</p><p class="tiny">This local notebook retains up to 16 kept versions and 24 frozen runs per case. Keeping a new version does not update an older one. A kept version carries its own run and human-reader snapshots even when older run history is removed.</p>${v.case.kept.length?`<div class="instruction-kept-list">${[...v.case.kept].reverse().map(keptSnapshot).join('')}</div>`:'<p>No versions kept yet. Unfinished or blank writing can be kept.</p>'}<a href="#notes">Open local notes and downloads</a></section>`;}
function helpPanel(v){const topic=v.case.helpTopic,c=v.source;let more='';if(topic==='purpose')more=`<h4>${esc(instructionComparison.label)}</h4><blockquote>${esc(instructionComparison.invitation)}</blockquote><p>${esc(instructionComparison.question)}</p><p>A preparation instruction: “${esc(instructionComparison.instruction)}”</p><p>${esc(instructionComparison.explanation)}</p>`;if(topic==='cause')more=`<blockquote>${esc(c.cause)}</blockquote><p>Compare:</p><blockquote>${esc(c.reversedCause)}</blockquote><p>${esc(c.causeExplanation)}</p><p>${esc(c.readerVariation)}</p>`;if(topic==='example'){const n=v.case.exampleStep;more=`<p>Ready-made example: ${instructionExample.sentences.map(esc).join(' ')}</p><div class="instruction-scene">${instructionToyExample(n)}</div><p role="status">${esc(instructionExample.steps[n])}</p><div class="instruction-actions">${button('Previous example scene',`data-instruction-example="-1" ${n===0?'disabled':''}`)}${button('Next example scene',`data-instruction-example="1" ${n>=instructionExample.steps.length-1?'disabled':''}`)}</div>`;}return `<details class="instruction-help" ${topic?'open':''}><summary>Some help, if you like</summary><div class="instruction-help-options">${instructionHelpTopics.map(t=>button(helpNames[t],`data-instruction-help="${t}" aria-pressed="${topic===t}"`)).join('')}</div>${topic?`<section id="instruction-help-content" tabindex="-1"><h3>${esc(helpNames[topic])}</h3><p>${esc(instructionHelp[topic])}</p>${more}${button('Close this help','data-instruction-help=""')}</section>`:''}</details>`;}
export function renderInstructions(state,desk='post'){
 const v=core.instructionView(state,desk);if(v.unsupported)return {html:`<div class="instruction-notebook">${header(desk)}<section><h2 id="instruction-title" tabindex="-1">An earlier notebook is retained</h2><p>This saved format cannot be opened here. Its exact original data remains in local notes and downloads.</p>${button('Keep the original and open a fresh notebook','data-instruction-recover',true)}<a href="#notes">Open local notes</a></section></div>`,facts:[]};
 const page=v.case.page,[heading,instruction]=intros[page],pages={purpose:purposePage,plan:planPage,strip:stripPage,words:wordsPage,read:humanPage,keep:keepPage};
 return {html:`<div class="instruction-notebook">${header(desk)}<label class="instruction-picker" for="instruction-case">Choose either note<select id="instruction-case">${instructionCases.map(c=>`<option value="${c.id}" ${v.source.id===c.id?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label><nav class="instruction-pages" aria-label="Instruction notebook pages">${instructionPages.map(p=>button(pageNames[p],`data-instruction-page="${p}" ${p===page?'aria-current="page"':''}`)).join('')}</nav><section class="instruction-current-task"><h2 id="instruction-title" tabindex="-1">${heading}</h2><p>${instruction}</p></section><div class="instruction-layout">${sourceBoard(v)}<div class="instruction-work">${pages[page](v,desk)}${helpPanel(v)}</div></div><footer class="instruction-footer"><p>Every page and both cases are open. Try, talk, keep, change or leave whenever you like.</p><a href="#post">My ordinary Post Office desk</a><a href="#loft">My ordinary puppet show</a><details><summary>What these local notes can tell us</summary><p>They keep ready-made arrangements, exact written text, explicit snapshots, displayed support and optional reports. They cannot observe rehearsal, comprehension, handwriting, spelling, independent writing or learning. Familiarity is not mastery.</p>${v.priorExposureUnknown?'<p>Earlier exposure is unknown after an unsupported notebook was retained.</p>':''}</details></footer></div>`,facts:[]};
}
export function instructionNotes(state){if(!Object.hasOwn(state,'instructionNotes'))return '';const v=core.instructionView(state);return `<details class="panel instruction-notes"><summary>Instructions for a Reader: shared notebook</summary>${core.instructionNotes(state).map(line=>`<p class="instruction-verbatim">${esc(line)}</p>`).join('')}<details><summary>Exact local records, including retained recovery data</summary><pre>${esc(JSON.stringify(v.unsupported?v.raw:v.root,null,2))}</pre></details><a href="#post/instructions">Open the instruction notebook</a></details>`;}

export function preserveInstructionBreaks(raw,visible){
 const normalized=raw.replace(/\r\n?/g,'\n');if(normalized===visible)return raw;
 let prefix=0,suffix=0;while(prefix<normalized.length&&prefix<visible.length&&normalized[prefix]===visible[prefix])prefix++;
 while(suffix<normalized.length-prefix&&suffix<visible.length-prefix&&normalized[normalized.length-1-suffix]===visible[visible.length-1-suffix])suffix++;
 const offsets=[0];for(let i=0;i<raw.length;){if(raw[i]==='\r'&&raw[i+1]==='\n')i+=2;else i++;offsets.push(i);}
 let before=raw.slice(0,offsets[prefix]);const middle=visible.slice(prefix,visible.length-suffix),after=raw.slice(offsets[normalized.length-suffix]);
 if(before.endsWith('\r')&&(middle+after).startsWith('\n'))before+='\n';
 const result=before+middle+after;return result.replace(/\r\n?/g,'\n')===visible?result:visible;
}
export function bindInstructions(state,desk,{save,render,navigate,focus}={}){
 const scope=document.querySelector('.instruction-notebook');if(!scope)return;
 const placeFocus=selector=>{const el=document.querySelector(selector);if(!el)return;focus?focus(selector):el.focus();};
 const act=(fn,target='#instruction-title')=>{const changed=fn();if(changed){save?.();render?.();}if(target)placeFocus(typeof target==='function'?target():target);return changed;};
 scope.querySelector('#instruction-case')?.addEventListener('change',e=>act(()=>core.chooseInstructionCase(state,desk,e.target.value)));
 scope.querySelectorAll('[data-instruction-page]').forEach(b=>b.onclick=()=>act(()=>core.setInstructionPage(state,desk,b.dataset.instructionPage)));
 scope.querySelectorAll('[data-instruction-edit]').forEach(b=>b.onclick=()=>{const group=b.dataset.instructionEdit;act(()=>group==='plan'?core.editInstructionPlan(state,desk,b.dataset.op,b.dataset.id):core.editInstructionStrip(state,desk,b.dataset.op,b.dataset.id,b.dataset.variant||'A'),()=>{if(b.dataset.op==='variant')return `#instruction-sentence-${b.dataset.id}`;const selector=`[data-instruction-edit="${group}"][data-op="${b.dataset.op}"][data-id="${b.dataset.id}"]${b.dataset.variant?`[data-variant="${b.dataset.variant}"]`:''}`;return document.querySelector(selector)&&!document.querySelector(selector).disabled?selector:`#instruction-${group}`;});});
 scope.querySelector('[data-instruction-copy]')?.addEventListener('click',()=>act(()=>{core.copyInstructionPlan(state,desk);return core.setInstructionPage(state,desk,'strip');},'#instruction-strip'));
 scope.querySelector('[data-instruction-try]')?.addEventListener('click',()=>act(()=>core.tryInstructionStrip(state,desk),'#instruction-run'));
 scope.querySelectorAll('[data-instruction-step]').forEach(b=>b.onclick=()=>act(()=>core.stepInstructionRun(state,desk,Number(b.dataset.instructionStep)),()=>{const selector=`[data-instruction-step="${b.dataset.instructionStep}"]`;return document.querySelector(selector)?.disabled?'#instruction-run':selector;}));
 scope.querySelectorAll('[data-instruction-run]').forEach(b=>b.onclick=()=>act(()=>core.selectInstructionRun(state,desk,Number(b.dataset.instructionRun)),'#instruction-run'));
 scope.querySelectorAll('[data-instruction-report]').forEach(input=>input.onchange=()=>{if(core.setInstructionReport(state,desk,input.dataset.instructionReport,input.value))save?.();});
 scope.querySelectorAll('[data-instruction-read],[data-instruction-question]').forEach(b=>b.onclick=()=>act(()=>{core.readInstructionWords(state,desk,b.dataset.instructionQuestion);return core.setInstructionPage(state,desk,'read');},'#instruction-human'));
 const textInput=(selector,read,write,errorId)=>{const input=scope.querySelector(selector);if(!input)return;
  input.value=read();
  input.addEventListener('input',()=>{const raw=preserveInstructionBreaks(read(),input.value),error=scope.querySelector(errorId);
   if(write(raw)){save?.();const stale=scope.querySelector('[data-instruction-human-stale]');if(stale){const current=core.instructionView(state,desk);stale.hidden=!current.humanRead||current.humanReadCurrent;}if(error)error.hidden=true;input.removeAttribute('aria-invalid');input.setAttribute('aria-describedby',selector==='[data-instruction-text]'?'instruction-text-note':'instruction-comment-note');}
   else if(error){error.textContent='These words are too long to save. Please shorten them; the saved words have been kept as they were.';error.hidden=false;input.setAttribute('aria-invalid','true');input.setAttribute('aria-describedby',error.id);}
  });};
 textInput('[data-instruction-text]',()=>core.instructionView(state,desk).case.text,value=>core.setInstructionText(state,desk,value),'#instruction-text-error');
 textInput('[data-instruction-comment]',()=>core.instructionView(state,desk).humanRead?.comment||'',value=>core.setInstructionComment(state,desk,value),'#instruction-comment-error');
 scope.querySelectorAll('[data-instruction-history-result]').forEach(d=>d.addEventListener('toggle',()=>{if(d.open&&core.useInstructionSupport(state,desk,'runFeedback'))save?.();}));
 scope.querySelectorAll('[data-instruction-help]').forEach(b=>b.onclick=()=>act(()=>core.setInstructionHelp(state,desk,b.dataset.instructionHelp||null),b.dataset.instructionHelp?'#instruction-help-content':'.instruction-help summary'));
 scope.querySelectorAll('[data-instruction-example]').forEach(b=>b.onclick=()=>act(()=>core.stepInstructionExample(state,desk,Number(b.dataset.instructionExample)),()=>{const selector=`[data-instruction-example="${b.dataset.instructionExample}"]`;return document.querySelector(selector)?.disabled?'#instruction-help-content':selector;}));
 scope.querySelector('[data-instruction-keep]')?.addEventListener('click',()=>act(()=>core.keepInstructionDraft(state,desk),'#instruction-kept-status'));
 scope.querySelectorAll('[data-instruction-update]').forEach(b=>b.onclick=()=>act(()=>core.updateInstructionKeep(state,desk,Number(b.dataset.instructionUpdate)),`#instruction-kept-${b.dataset.instructionUpdate}`));
 scope.querySelector('[data-instruction-recover]')?.addEventListener('click',()=>act(()=>core.recoverInstructions(state)));
 scope.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',()=>{if(core.useInstructionSupport(state,desk,'narration'))save?.();},{capture:true}));
}
